INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5770947, 840325, 103142, '<td valign="top">whoa!! this is really creepy! I don''t think I should have seen this one before bedtime...<br/> <br/>Nicely done. I don''t know how rural it is, but I''ll believe it.</td>', 'whoa!! this is really creepy! I don''t think I should have seen this one before bedtime... Nicely done. I don''t know how rural it is, but I''ll believe it.', '2009-12-18 00:03:34.000000', NULL, 1),
(5770951, 839805, 54645, '<td valign="top">Looks like a <a href="//www.dpchallenge.com/profile.php?USER_ID=63398" rel="nofollow" target="_blank">Jeb!</a> Excellent composition and texture.</td>', 'Looks like a Jeb! Excellent composition and texture.', '2009-12-18 00:06:23.000000', NULL, 1),
(5770954, 840263, 54645, '<td valign="top">I had lunch there last week!</td>', 'I had lunch there last week!', '2009-12-18 00:06:48.000000', NULL, 1),
(5771007, 840263, 15511, '<td valign="top">The darkness of the foreground says this image is mostly about the sky. I think lightening the foreground shadows would carry the message more effectively. Mild HDR or PS shadows/<strike>highlights</strike> followed by some contrast enhancement could be effective tools.</td>', 'The darkness of the foreground says this image is mostly about the sky. I think lightening the foreground shadows would carry the message more effectively. Mild HDR or PS shadows/highlights followed by some contrast enhancement could be effective tools.', '2009-12-18 01:22:18.000000', NULL, 1),
(5771009, 839916, 25190, '<td valign="top">Wondeful image i like the colors and the cloud formation great depth of field really adds to the image</td>', 'Wondeful image i like the colors and the cloud formation great depth of field really adds to the image', '2009-12-18 01:23:40.000000', NULL, 1),
(5771010, 840429, 25190, '<td valign="top">she has been guttered goodtime</td>', 'she has been guttered goodtime', '2009-12-18 01:25:39.000000', NULL, 1),
(5771011, 840375, 25190, '<td valign="top">Good capture of the subject i like how the cloud/fog roll in the background  good rule of the third</td>', 'Good capture of the subject i like how the cloud/fog roll in the background  good rule of the third', '2009-12-18 01:25:45.000000', NULL, 1),
(5771012, 839439, 25190, '<td valign="top">i feel its abit to busy to much in the image if it was closer to the subject would have been better still a good take of rural decay</td>', 'i feel its abit to busy to much in the image if it was closer to the subject would have been better still a good take of rural decay', '2009-12-18 01:25:48.000000', NULL, 1),
(5771025, 840437, 112218, '<td valign="top">Interesting angles.<br/>Well placed off centre.<br/>Good shot.<br/>Sorry can''t vote but good luck.</td>', 'Interesting angles.Well placed off centre.Good shot.Sorry can''t vote but good luck.', '2009-12-18 01:58:56.000000', NULL, 1),
(5771026, 839915, 112218, '<td valign="top">Stunning shot!<br/>Maybe a bit too much sky but can see why you left it in.<br/>Sorry can''t vote but good luck.</td>', 'Stunning shot!Maybe a bit too much sky but can see why you left it in.Sorry can''t vote but good luck.', '2009-12-18 02:00:05.000000', NULL, 1),
(5771027, 839805, 112218, '<td valign="top">Well caught.<br/>Good angles.<br/>Maybe a bit more contrast needed IMO.<br/>Can''t vote but good luck.</td>', 'Well caught.Good angles.Maybe a bit more contrast needed IMO.Can''t vote but good luck.', '2009-12-18 02:01:13.000000', NULL, 1),
(5771028, 840264, 112218, '<td valign="top">Colours seem a bit washed-out.<br/>Good subject matter.</td>', 'Colours seem a bit washed-out.Good subject matter.', '2009-12-18 02:01:56.000000', NULL, 1),
(5771036, 840367, 99710, '<td valign="top">lovely tones and texture. nice work.</td>', 'lovely tones and texture. nice work.', '2009-12-18 02:22:09.000000', NULL, 1),
(5771037, 840364, 99710, '<td valign="top">Beautiful photo but I don''t see where the decay is...</td>', 'Beautiful photo but I don''t see where the decay is...', '2009-12-18 02:24:31.000000', NULL, 1),
(5771038, 839397, 99710, '<td valign="top">Beautiful work. 10</td>', 'Beautiful work. 10', '2009-12-18 02:26:00.000000', NULL, 1),
(5771039, 840318, 99710, '<td valign="top">Great still-life photo. Excellent tones and textures.</td>', 'Great still-life photo. Excellent tones and textures.', '2009-12-18 02:26:51.000000', NULL, 1),
(5771076, 840431, 99710, '<td valign="top">minus the blurred portion in the foreground, this photo looks great.</td>', 'minus the blurred portion in the foreground, this photo looks great.', '2009-12-18 04:28:09.000000', NULL, 1),
(5771078, 840082, 99710, '<td valign="top">i am half-hearted with the grass in the foreground, i am not sure whether to like it or not, but the background and the tree looks terrific!</td>', 'i am half-hearted with the grass in the foreground, i am not sure whether to like it or not, but the background and the tree looks terrific!', '2009-12-18 04:29:27.000000', NULL, 1),
(5771097, 839900, 110744, '<td valign="top">Beautiful light and shadow. The textures and depth are wonderful.</td>', 'Beautiful light and shadow. The textures and depth are wonderful.', '2009-12-18 05:12:45.000000', NULL, 1),
(5771113, 840429, 68769, '<td valign="top">Very Jeb like, thats a good thing..</td>', 'Very Jeb like, thats a good thing..', '2009-12-18 06:23:15.000000', NULL, 1),
(5771116, 840263, 100393, '<td valign="top">I do like this great scene but (I almost hate myself for saying this) it seems under-edited. Perhaps you wanted a very authentic depiction and I should respect that but I feel there is so much untapped potential in this image (in terms of contrast, colour, tone and texture).<br/> <br/>I''d be really interested to know whether that was an active choice or absence of software.</td>', 'I do like this great scene but (I almost hate myself for saying this) it seems under-edited. Perhaps you wanted a very authentic depiction and I should respect that but I feel there is so much untapped potential in this image (in terms of contrast, colour, tone and texture). I''d be really interested to know whether that was an active choice or absence of software.', '2009-12-18 06:29:57.000000', NULL, 1),
(5771118, 839586, 100393, '<td valign="top">Pristine image.</td>', 'Pristine image.', '2009-12-18 06:32:03.000000', NULL, 1),
(5771121, 840265, 100393, '<td valign="top">I really like this - nice soft light.</td>', 'I really like this - nice soft light.', '2009-12-18 06:34:28.000000', NULL, 1),
(5771122, 840438, 100393, '<td valign="top">Very interesting image - a nice break from (the fine examples of) rusting farm machinery.</td>', 'Very interesting image - a nice break from (the fine examples of) rusting farm machinery.', '2009-12-18 06:36:12.000000', NULL, 1),
(5771124, 840261, 100393, '<td valign="top">Tremendous, bold stuff.</td>', 'Tremendous, bold stuff.', '2009-12-18 06:38:00.000000', NULL, 1),
(5771125, 840318, 100393, '<td valign="top">Very well executed grungy shot.</td>', 'Very well executed grungy shot.', '2009-12-18 06:38:22.000000', NULL, 1),
(5771128, 840054, 100393, '<td valign="top">I think this should ribbon.</td>', 'I think this should ribbon.', '2009-12-18 06:42:11.000000', NULL, 1),
(5771129, 840325, 100393, '<td valign="top">This works really well.</td>', 'This works really well.', '2009-12-18 06:45:56.000000', NULL, 1),
(5771177, 840082, 103958, '<td valign="top">Very cool. I like the texture of the trees in the background.</td>', 'Very cool. I like the texture of the trees in the background.', '2009-12-18 08:13:55.000000', NULL, 1),
(5771180, 839534, 103958, '<td valign="top">nice reflection.</td>', 'nice reflection.', '2009-12-18 08:17:03.000000', NULL, 1),
(5771232, 840253, 57447, '<td valign="top">I like the way the shed sits in the photo and the tone used.  It depicts rural decay imho.</td>', 'I like the way the shed sits in the photo and the tone used.  It depicts rural decay imho.', '2009-12-18 08:42:23.000000', NULL, 1),
(5771251, 840323, 58691, '<td valign="top">While this does indicate decay, nothing about this scene says "rural".</td>', 'While this does indicate decay, nothing about this scene says "rural".', '2009-12-18 09:09:52.000000', NULL, 1),
(5771253, 839489, 58691, '<td valign="top">The</td>', 'The', '2009-12-18 09:10:19.000000', NULL, 1),
(5771255, 840400, 58691, '<td valign="top">The fence post is an obstruction/barrier to the rest of the image</td>', 'The fence post is an obstruction/barrier to the rest of the image', '2009-12-18 09:11:37.000000', NULL, 1),
(5771260, 840263, 65234, '<td valign="top">It does look lonely.  Not as decrepit as a lot of abandoned places and the perspective seems rather ordinary to me.  Might have been more interesting to me from down lower and/or a different angle.</td>', 'It does look lonely.  Not as decrepit as a lot of abandoned places and the perspective seems rather ordinary to me.  Might have been more interesting to me from down lower and/or a different angle.', '2009-12-18 09:18:04.000000', NULL, 1),
(5771261, 840018, 65234, '<td valign="top">Looks like it once supported a good-sized structure.  Like the wonderful old stone and the grasses leading to the ruins.</td>', 'Looks like it once supported a good-sized structure.  Like the wonderful old stone and the grasses leading to the ruins.', '2009-12-18 09:19:33.000000', NULL, 1),
(5771262, 840432, 65234, '<td valign="top">Distorted perspective is a fun way to see this.</td>', 'Distorted perspective is a fun way to see this.', '2009-12-18 09:20:51.000000', NULL, 1),
(5771265, 840392, 65234, '<td valign="top">I want to look in the window at all that junk piled up inside.  There could be real finds in there!  You chose a wider view which does work better for this challenge, I suppose, but I wouldn''t like it nearly as well without that window to intrigue me.  Nice find.</td>', 'I want to look in the window at all that junk piled up inside.  There could be real finds in there!  You chose a wider view which does work better for this challenge, I suppose, but I wouldn''t like it nearly as well without that window to intrigue me.  Nice find.', '2009-12-18 09:24:12.000000', NULL, 1),
(5771278, 840417, 65234, '<td valign="top">That''s a very cool subject!  Looking a little flat on my screen; might benefit from a contrast boost and maybe some burning on those background trees to give it more depth.</td>', 'That''s a very cool subject!  Looking a little flat on my screen; might benefit from a contrast boost and maybe some burning on those background trees to give it more depth.', '2009-12-18 09:31:15.000000', NULL, 1),
(5771280, 839862, 65234, '<td valign="top">Very decayed!  Not sure the centered composition is working for me; I think I''d crop tighter on the left and top to better showcase the shed.</td>', 'Very decayed!  Not sure the centered composition is working for me; I think I''d crop tighter on the left and top to better showcase the shed.', '2009-12-18 09:34:01.000000', NULL, 1),
(5771282, 840398, 109640, '<td valign="top">Really like the Picture! great detail</td>', 'Really like the Picture! great detail', '2009-12-18 09:34:50.000000', NULL, 1),
(5771284, 840416, 65234, '<td valign="top">Nice find.  Something about the realistic leaves on the top left and the cartoonish tire below is disconcerting to me, like they belong to different images.</td>', 'Nice find.  Something about the realistic leaves on the top left and the cartoonish tire below is disconcerting to me, like they belong to different images.', '2009-12-18 09:36:02.000000', NULL, 1),
(5771289, 840289, 109640, '<td valign="top">Really like the look of the sky!</td>', 'Really like the look of the sky!', '2009-12-18 09:38:31.000000', NULL, 1),
(5771290, 840224, 65234, '<td valign="top">Nicely picturesque barn.  Think I''d prefer a bit less smoothness here.</td>', 'Nicely picturesque barn.  Think I''d prefer a bit less smoothness here.', '2009-12-18 09:38:47.000000', NULL, 1),
(5771291, 840258, 65234, '<td valign="top">Reflection is a nice addition to the scene.</td>', 'Reflection is a nice addition to the scene.', '2009-12-18 09:39:34.000000', NULL, 1),
(5771297, 840403, 65234, '<td valign="top">Like the glimpse of the inside; makes me want to wander over and peek in.</td>', 'Like the glimpse of the inside; makes me want to wander over and peek in.', '2009-12-18 09:42:16.000000', NULL, 1),
(5771299, 840399, 109640, '<td valign="top">Very nice picture! Great job</td>', 'Very nice picture! Great job', '2009-12-18 09:44:51.000000', NULL, 1),
(5771306, 840402, 65234, '<td valign="top">Almost looks like there might be a big eyeball peeking out from the dark.</td>', 'Almost looks like there might be a big eyeball peeking out from the dark.', '2009-12-18 09:48:21.000000', NULL, 1),
(5771307, 840417, 109640, '<td valign="top">That bridge is really cool! Great Picture!</td>', 'That bridge is really cool! Great Picture!', '2009-12-18 09:48:27.000000', NULL, 1),
(5771310, 840412, 65234, '<td valign="top">Seriously rusted.  Looks almost like suburban houses behind it; if possible I''d shoot from even farther down if it would get them out of the shot.  Light is quite harsh (like from an undiffused flash).</td>', 'Seriously rusted.  Looks almost like suburban houses behind it; if possible I''d shoot from even farther down if it would get them out of the shot.  Light is quite harsh (like from an undiffused flash).', '2009-12-18 09:51:48.000000', NULL, 1),
(5771312, 840318, 65234, '<td valign="top">Painterly sort of image.  Like the composition.</td>', 'Painterly sort of image.  Like the composition.', '2009-12-18 09:52:21.000000', NULL, 1),
(5771316, 840300, 65234, '<td valign="top">Doesn''t actually look that decayed to me, but it''s very bright and I may be missing some detail.</td>', 'Doesn''t actually look that decayed to me, but it''s very bright and I may be missing some detail.', '2009-12-18 09:54:46.000000', NULL, 1),
(5771320, 840299, 65234, '<td valign="top">Nice old barn.  Looks on my screen like it could use a contrast boost and maybe a tad more sharpening to really bring out the detail.</td>', 'Nice old barn.  Looks on my screen like it could use a contrast boost and maybe a tad more sharpening to really bring out the detail.', '2009-12-18 09:58:15.000000', NULL, 1),
(5771322, 840385, 65234, '<td valign="top">In the way of progress, I see.  I''d love 9 acres, but not across the street from a strip mall!  Not nearly as decayed as I''d expect but it certainly does tell a story.</td>', 'In the way of progress, I see.  I''d love 9 acres, but not across the street from a strip mall!  Not nearly as decayed as I''d expect but it certainly does tell a story.', '2009-12-18 09:59:47.000000', NULL, 1),
(5771323, 840437, 65234, '<td valign="top">Like the "EEP" sign ;-)  Nicely decrepit scene.</td>', 'Like the "EEP" sign ;-)  Nicely decrepit scene.', '2009-12-18 10:01:01.000000', NULL, 1),
(5771326, 840410, 65234, '<td valign="top">Looks to be pretty sturdy still.  Maybe it''s the strength of the silhouette.</td>', 'Looks to be pretty sturdy still.  Maybe it''s the strength of the silhouette.', '2009-12-18 10:03:47.000000', NULL, 1),
(5771328, 840394, 65234, '<td valign="top">Whimsical, but not much decay in evidence.</td>', 'Whimsical, but not much decay in evidence.', '2009-12-18 10:04:51.000000', NULL, 1),
(5771329, 840430, 65234, '<td valign="top">Interesting subject well captured.  I don''t generally prefer straight-on shots but in this case the natural stair-step diagonal of the structure''s top outline makes it work.</td>', 'Interesting subject well captured.  I don''t generally prefer straight-on shots but in this case the natural stair-step diagonal of the structure''s top outline makes it work.', '2009-12-18 10:07:28.000000', NULL, 1),
(5771331, 840390, 65234, '<td valign="top">Messy, but the structure dosn''t look decayed at all.  Msybe could use a paint job.  Overall focus looks soft to me.</td>', 'Messy, but the structure dosn''t look decayed at all.  Msybe could use a paint job.  Overall focus looks soft to me.', '2009-12-18 10:10:26.000000', NULL, 1),
(5771332, 840404, 65234, '<td valign="top">:-)  Gotta'' love the decor with the decay.</td>', ':-)  Gotta'' love the decor with the decay.', '2009-12-18 10:11:11.000000', NULL, 1),
(5771336, 840179, 65234, '<td valign="top">Interesting image, but looks to be very much in use with all those manmade rows and tracks, and the darker field looks irrigated.  But then maybe it was all once green.</td>', 'Interesting image, but looks to be very much in use with all those manmade rows and tracks, and the darker field looks irrigated.  But then maybe it was all once green.', '2009-12-18 10:18:16.000000', NULL, 1),
(5771338, 839489, 65234, '<td valign="top">Nice detail.  For this challenge I would have cropped out the high rise buildings on the right to make the context more ambiguous.</td>', 'Nice detail.  For this challenge I would have cropped out the high rise buildings on the right to make the context more ambiguous.', '2009-12-18 10:19:34.000000', NULL, 1),
(5771342, 839612, 65234, '<td valign="top">Stands out quite nicely in the snow.</td>', 'Stands out quite nicely in the snow.', '2009-12-18 10:24:52.000000', NULL, 1),
(5771345, 840398, 65234, '<td valign="top">Pretty warm colors, even with the snow.</td>', 'Pretty warm colors, even with the snow.', '2009-12-18 10:31:33.000000', NULL, 1),
(5771363, 840372, 112589, '<td valign="top">you blow goats</td>', 'you blow goats', '2009-12-18 10:59:25.000000', NULL, 1),
(5771382, 840082, 10523, '<td valign="top">great shot- should be a ribbon</td>', 'great shot- should be a ribbon', '2009-12-18 11:40:58.000000', NULL, 1),
(5771383, 839916, 10523, '<td valign="top">great shot- my number 1 in the challenge</td>', 'great shot- my number 1 in the challenge', '2009-12-18 11:41:12.000000', NULL, 1),
(5771384, 840049, 10523, '<td valign="top">nice shot, nice title, top 10</td>', 'nice shot, nice title, top 10', '2009-12-18 11:41:23.000000', NULL, 1),
(5771385, 839805, 10523, '<td valign="top">great shot- top 5</td>', 'great shot- top 5', '2009-12-18 11:41:33.000000', NULL, 1),
(5771386, 840372, 10523, '<td valign="top">great concept- top 10</td>', 'great concept- top 10', '2009-12-18 11:41:44.000000', NULL, 1),
(5771387, 840402, 10523, '<td valign="top">nice shot- top 10</td>', 'nice shot- top 10', '2009-12-18 11:41:55.000000', NULL, 1),
(5771388, 840399, 10523, '<td valign="top">nice shot- top 5</td>', 'nice shot- top 5', '2009-12-18 11:42:05.000000', NULL, 1),
(5771389, 839461, 10523, '<td valign="top">nice shot- top 10</td>', 'nice shot- top 10', '2009-12-18 11:42:14.000000', NULL, 1),
(5771429, 840297, 83313, '<td valign="top">I like the grainy b/w and the vignette works as well. I have an outtake that was a similar subject, but not nearly as good.</td>', 'I like the grainy b/w and the vignette works as well. I have an outtake that was a similar subject, but not nearly as good.', '2009-12-18 12:38:59.000000', NULL, 1),
(5771430, 840410, 83313, '<td valign="top">Kindof on the too simple side. Usually such a silhouette has strong visual impact, but I''m not quite sure what this needs. Maybe it''s too zoomed in and centered.</td>', 'Kindof on the too simple side. Usually such a silhouette has strong visual impact, but I''m not quite sure what this needs. Maybe it''s too zoomed in and centered.', '2009-12-18 12:40:47.000000', NULL, 1),
(5771434, 840299, 83313, '<td valign="top">Nice detail and good subject. A little stronger on the colors would probably add some decent pointage.</td>', 'Nice detail and good subject. A little stronger on the colors would probably add some decent pointage.', '2009-12-18 12:47:01.000000', NULL, 1),
(5771435, 840402, 83313, '<td valign="top">Good strong mono work.</td>', 'Good strong mono work.', '2009-12-18 12:47:41.000000', NULL, 1),
(5771442, 840033, 83313, '<td valign="top">Looks like an old pic from he early 50''s, but it''s not having much impact on me. A few things might make a difference...<br/> <br/>-Stronger contrast<br/>-Wider or narrower view of the scene. This seems to be a bit tight of a crop, but not intentionally so. (Does that make any sense?)<br/>-A slight vignette can help add to a nostalgic look. Getting an effective vignette is something I am still working on.<br/>-Though certainly something found in rural areas, this style of house may not be screaming "rural" to many voters.</td>', 'Looks like an old pic from he early 50''s, but it''s not having much impact on me. A few things might make a difference... -Stronger contrast-Wider or narrower view of the scene. This seems to be a bit tight of a crop, but not intentionally so. (Does that make any sense?)-A slight vignette can help add to a nostalgic look. Getting an effective vignette is something I am still working on.-Though certainly something found in rural areas, this style of house may not be screaming "rural" to many voters.', '2009-12-18 12:54:26.000000', NULL, 1),
(5771443, 840366, 83313, '<td valign="top">It''s an interesting subject. A decent shot, though perhaps a different perspective on it may have lent more impact to it. (I realize you may not have had the ability to get closer, such things are often set back on private property.)</td>', 'It''s an interesting subject. A decent shot, though perhaps a different perspective on it may have lent more impact to it. (I realize you may not have had the ability to get closer, such things are often set back on private property.)', '2009-12-18 12:57:12.000000', NULL, 1),
(5771444, 839803, 83313, '<td valign="top">Looks almost like an Amazon jungle.</td>', 'Looks almost like an Amazon jungle.', '2009-12-18 12:57:47.000000', NULL, 1),
(5771447, 840175, 83313, '<td valign="top">Composition does not seem to be leading my eye around well, and the strong yellow cast does not work well for me. It''s a good effort that''s just not working for me.</td>', 'Composition does not seem to be leading my eye around well, and the strong yellow cast does not work well for me. It''s a good effort that''s just not working for me.', '2009-12-18 13:01:01.000000', NULL, 1),
(5771449, 840429, 83313, '<td valign="top">A very <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=63398" rel="nofollow" target="_blank">NikonJeb</a>ish looking shot, but I know it''s not his. I expect this will do well.</td>', 'A very  NikonJebish looking shot, but I know it''s not his. I expect this will do well.', '2009-12-18 13:03:09.000000', NULL, 1),
(5771451, 840224, 83313, '<td valign="top">Processing gives this almost an painting-like look, but I like it for this scene.</td>', 'Processing gives this almost an painting-like look, but I like it for this scene.', '2009-12-18 13:04:19.000000', NULL, 1),
(5771452, 840430, 83313, '<td valign="top">These backlit, near-dark scenes are always tough for me to bring detail out of and have it look good. You did well.</td>', 'These backlit, near-dark scenes are always tough for me to bring detail out of and have it look good. You did well.', '2009-12-18 13:05:37.000000', NULL, 1),
(5771453, 840308, 83313, '<td valign="top">Coming across to me as a snapshot, I''m afraid. The light seems kind of flat. Was flash used?</td>', 'Coming across to me as a snapshot, I''m afraid. The light seems kind of flat. Was flash used?', '2009-12-18 13:08:10.000000', NULL, 1),
(5771454, 840253, 83313, '<td valign="top">Oh, nice. We can make a clubhouse out of this shed! The perfect place for Team Suck to meet!</td>', 'Oh, nice. We can make a clubhouse out of this shed! The perfect place for Team Suck to meet!', '2009-12-18 13:09:08.000000', NULL, 1),
(5771456, 840266, 83313, '<td valign="top">Dramatic looking. Good job on the PP, heavy handed, but not over-the-top.</td>', 'Dramatic looking. Good job on the PP, heavy handed, but not over-the-top.', '2009-12-18 13:10:21.000000', NULL, 1),
(5771459, 840300, 83313, '<td valign="top">Cool looking old tractor. Details seem a bit jaggy. Might be an issue with the resizing to challenge size.</td>', 'Cool looking old tractor. Details seem a bit jaggy. Might be an issue with the resizing to challenge size.', '2009-12-18 13:13:03.000000', NULL, 1),
(5771460, 839916, 83313, '<td valign="top">Sweet. You made good use of the orange sunset tones. I often have difficulty with them being far too yellowy.</td>', 'Sweet. You made good use of the orange sunset tones. I often have difficulty with them being far too yellowy.', '2009-12-18 13:16:20.000000', NULL, 1),
(5771464, 839868, 83313, '<td valign="top">Great landscape, but it is not screaming "decay" to me except for the title. Perhaps the tree is dead? Should do well in spite of that.</td>', 'Great landscape, but it is not screaming "decay" to me except for the title. Perhaps the tree is dead? Should do well in spite of that.', '2009-12-18 13:22:04.000000', NULL, 1),
