(5771599, 839220, 83686, '<td valign="top">Too difficult for the viewer to understand what the image is without the title. The picture seems out of focus and the angle of the hill doesn''t work too well here.</td>', 'Too difficult for the viewer to understand what the image is without the title. The picture seems out of focus and the angle of the hill doesn''t work too well here.', '2009-12-18 17:01:17.000000', NULL, 1),
(5771601, 840390, 83686, '<td valign="top">Too busy and it seems out of focus(or maybe I can''t keep focused on any one thing). Perhaps if the shot was more focused on the decor with a blurred(bokeh)background ot might have been netter for me.</td>', 'Too busy and it seems out of focus(or maybe I can''t keep focused on any one thing). Perhaps if the shot was more focused on the decor with a blurred(bokeh)background ot might have been netter for me.', '2009-12-18 17:03:39.000000', NULL, 1),
(5771603, 840179, 83686, '<td valign="top">Aerial views are hard to make interesting IMO. The colors in the field(green) pull focus from the rest of the picture. Perhaps a different cropping of the photo would have made it better for me.</td>', 'Aerial views are hard to make interesting IMO. The colors in the field(green) pull focus from the rest of the picture. Perhaps a different cropping of the photo would have made it better for me.', '2009-12-18 17:05:59.000000', NULL, 1),
(5771607, 840325, 83686, '<td valign="top">Dolls like this creep me out, sorry...I think this would do better with more background because I just don''t get that "Rural" feel from this shot.</td>', 'Dolls like this creep me out, sorry...I think this would do better with more background because I just don''t get that "Rural" feel from this shot.', '2009-12-18 17:07:31.000000', NULL, 1),
(5771610, 840323, 83686, '<td valign="top">Hard to tell if this is Rural or not. I think if this was taken on a angle to show additional background it would work better IMO.</td>', 'Hard to tell if this is Rural or not. I think if this was taken on a angle to show additional background it would work better IMO.', '2009-12-18 17:08:41.000000', NULL, 1),
