(5771685, 840409, 65234, '<td valign="top">Very nice!  I love the jar on the counter, like someone just walked out in the middle of doing something and never came back.  Quite intriguing.</td>', 'Very nice!  I love the jar on the counter, like someone just walked out in the middle of doing something and never came back.  Quite intriguing.', '2009-12-18 18:08:42.000000', NULL, 1),
(5771686, 839803, 65234, '<td valign="top">Nice skylight ;-)  Lots of fun detail in this one; I particularly like the tile stubbornly resisting the overgrowth claiming the rest of the walls.</td>', 'Nice skylight ;-)  Lots of fun detail in this one; I particularly like the tile stubbornly resisting the overgrowth claiming the rest of the walls.', '2009-12-18 18:08:54.000000', NULL, 1),
(5771687, 840054, 65234, '<td valign="top">Looks like some sort of modern art sculpture!  Very interesting.</td>', 'Looks like some sort of modern art sculpture!  Very interesting.', '2009-12-18 18:09:02.000000', NULL, 1),
(5771688, 840082, 65234, '<td valign="top">Like this subject; makes me wonder about what was once there attached to the fireplace.  Something grand, I think.  I might do some selective burning to give a bit more depth to the background, though the grayness of it does suit a skeletal theme.</td>', 'Like this subject; makes me wonder about what was once there attached to the fireplace.  Something grand, I think.  I might do some selective burning to give a bit more depth to the background, though the grayness of it does suit a skeletal theme.', '2009-12-18 18:09:15.000000', NULL, 1),
