(5772045, 840416, 112218, '<td valign="top">Excellent comp and colours.<br/>Good angle.<br/>Sorry can''t vote but good luck.</td>', 'Excellent comp and colours.Good angle.Sorry can''t vote but good luck.', '2009-12-19 07:56:19.000000', NULL, 1),
(5772046, 839862, 112218, '<td valign="top">Well caught.<br/>Perhaps a bit more ground and less sky would have made quite a difference.</td>', 'Well caught.Perhaps a bit more ground and less sky would have made quite a difference.', '2009-12-19 07:57:52.000000', NULL, 1),
(5772047, 839461, 112218, '<td valign="top">Nice detail.<br/>Good use of thirds.</td>', 'Nice detail.Good use of thirds.', '2009-12-19 07:58:38.000000', NULL, 1),
(5772048, 840404, 112218, '<td valign="top">Good colour and placement in frame.<br/>Wonder where they went.....</td>', 'Good colour and placement in frame.Wonder where they went.....', '2009-12-19 07:59:47.000000', NULL, 1),
(5772081, 840289, 65234, '<td valign="top">Very broody sky which suits the theme. Maybe a tad oversaturated.</td>', 'Very broody sky which suits the theme. Maybe a tad oversaturated.', '2009-12-19 09:05:02.000000', NULL, 1),
(5772084, 840438, 65234, '<td valign="top">Interesting perspective, maybe even old, leaded glass, but this suggests rural relaxation more so than decay to me.</td>', 'Interesting perspective, maybe even old, leaded glass, but this suggests rural relaxation more so than decay to me.', '2009-12-19 09:06:45.000000', NULL, 1),
(5772086, 840033, 65234, '<td valign="top">Heh.  Those are definitely going the way of the dinosaur.</td>', 'Heh.  Those are definitely going the way of the dinosaur.', '2009-12-19 09:07:40.000000', NULL, 1),
(5772088, 840372, 65234, '<td valign="top">Different take on the challenge but it works.  Wonderfully twisty old roots.</td>', 'Different take on the challenge but it works.  Wonderfully twisty old roots.', '2009-12-19 09:08:32.000000', NULL, 1),
(5772092, 840049, 65234, '<td valign="top">A pretty picture but it just looks like a deciduous tree in winter.  Maybe a few dead branches.  It will probably be a long time till this one really looks decayed.</td>', 'A pretty picture but it just looks like a deciduous tree in winter.  Maybe a few dead branches.  It will probably be a long time till this one really looks decayed.', '2009-12-19 09:11:34.000000', NULL, 1),
(5772093, 839900, 65234, '<td valign="top">Nicely composed.</td>', 'Nicely composed.', '2009-12-19 09:11:50.000000', NULL, 1),
(5772094, 839220, 65234, '<td valign="top">Interesting juxtaposition; a bit softer than I like overall.</td>', 'Interesting juxtaposition; a bit softer than I like overall.', '2009-12-19 09:12:26.000000', NULL, 1),
(5772096, 839586, 65234, '<td valign="top">A stretch in my mind for this challenge.  I''d prefer to see what needs repairing.</td>', 'A stretch in my mind for this challenge.  I''d prefer to see what needs repairing.', '2009-12-19 09:13:16.000000', NULL, 1),
(5772097, 839805, 65234, '<td valign="top">Pretty much perfect for this challenge.  Love the view of the pews and then all the way through to the woods on the other side.</td>', 'Pretty much perfect for this challenge.  Love the view of the pews and then all the way through to the woods on the other side.', '2009-12-19 09:14:12.000000', NULL, 1),
(5772098, 840253, 65234, '<td valign="top">Nice find; I like the perspective with the door open and the view through the window to the other side.  A bit soft overall.</td>', 'Nice find; I like the perspective with the door open and the view through the window to the other side.  A bit soft overall.', '2009-12-19 09:15:14.000000', NULL, 1),
(5772100, 840261, 65234, '<td valign="top">Different.  Not sure what I think about the pristine cat''s paw and shiny ornament, but they do contrast with the pitifully bare tree.  Ambiguous setting.  Interesting ...</td>', 'Different.  Not sure what I think about the pristine cat''s paw and shiny ornament, but they do contrast with the pitifully bare tree.  Ambiguous setting.  Interesting ...', '2009-12-19 09:19:52.000000', NULL, 1),
(5772102, 839439, 65234, '<td valign="top">Great leading lines.  Looks like it was once homey and beautiful.</td>', 'Great leading lines.  Looks like it was once homey and beautiful.', '2009-12-19 09:20:53.000000', NULL, 1),
(5772104, 839915, 65234, '<td valign="top">Gorgeous image.  Not the best example of decay I''ve seen, but there is some here in the leaning posts.</td>', 'Gorgeous image.  Not the best example of decay I''ve seen, but there is some here in the leaning posts.', '2009-12-19 09:22:23.000000', NULL, 1),
(5772105, 840265, 65234, '<td valign="top">And some eejits graffiti''d up the place.  It must have been lovely, once.</td>', 'And some eejits graffiti''d up the place.  It must have been lovely, once.', '2009-12-19 09:23:49.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5772107, 839623, 65234, '<td valign="top">Guess that fence has a hole somewhere or some enterprising kids figured out how to get over it.  Looks like this was once serious agribusiness.</td>', 'Guess that fence has a hole somewhere or some enterprising kids figured out how to get over it.  Looks like this was once serious agribusiness.', '2009-12-19 09:25:05.000000', NULL, 1),
(5772108, 839975, 65234, '<td valign="top">Nice find, well shot.</td>', 'Nice find, well shot.', '2009-12-19 09:25:21.000000', NULL, 1),
(5772109, 840399, 65234, '<td valign="top">There is a warmth to the colors that I really like.  Good angle and composition.</td>', 'There is a warmth to the colors that I really like.  Good angle and composition.', '2009-12-19 09:26:31.000000', NULL, 1),
(5772110, 840431, 65234, '<td valign="top">Like the composition.  Rust is evident, though that appears to be mounted in some way so I''m betting the rust is managed ;-)</td>', 'Like the composition.  Rust is evident, though that appears to be mounted in some way so I''m betting the rust is managed ;-)', '2009-12-19 09:27:54.000000', NULL, 1),
(5772113, 840433, 65234, '<td valign="top">The blinds are quite poignant, and what seems to be a note tacked to the inside of the window.  One last thing to remember to do before leaving forever.</td>', 'The blinds are quite poignant, and what seems to be a note tacked to the inside of the window.  One last thing to remember to do before leaving forever.', '2009-12-19 09:29:20.000000', NULL, 1),
(5772114, 840323, 65234, '<td valign="top">Like that they left the "will return" sign.</td>', 'Like that they left the "will return" sign.', '2009-12-19 09:30:29.000000', NULL, 1),
(5772125, 840386, 65234, '<td valign="top">Like the light, though the warmth of it contradicts the feeling of abandonment to some extent.</td>', 'Like the light, though the warmth of it contradicts the feeling of abandonment to some extent.', '2009-12-19 09:33:08.000000', NULL, 1),
(5772126, 839456, 65234, '<td valign="top">Looks a bit like a Septa logo on that train.  Nice find with the auto and train in the weeds.</td>', 'Looks a bit like a Septa logo on that train.  Nice find with the auto and train in the weeds.', '2009-12-19 09:34:54.000000', NULL, 1),
(5772128, 839916, 65234, '<td valign="top">Love that golden light!</td>', 'Love that golden light!', '2009-12-19 09:36:07.000000', NULL, 1),
(5772203, 840398, 15711, '<td valign="top">I love this!!!!!</td>', 'I love this!!!!!', '2009-12-19 11:17:33.000000', NULL, 1),
(5772206, 839612, 19178, '<td valign="top">What a great color!!</td>', 'What a great color!!', '2009-12-19 11:26:38.000000', NULL, 1),
(5772207, 840378, 19178, '<td valign="top">This image is just too small to compete.</td>', 'This image is just too small to compete.', '2009-12-19 11:27:28.000000', NULL, 1),
(5772208, 839534, 19178, '<td valign="top">Neat reflection.</td>', 'Neat reflection.', '2009-12-19 11:27:44.000000', NULL, 1),
(5772259, 840406, 104849, '<td valign="top">Great picture, sharp and fits the challenge perfectly...Bravo!</td>', 'Great picture, sharp and fits the challenge perfectly...Bravo!', '2009-12-19 12:41:42.000000', NULL, 1),
(5772289, 840261, 50695, '<td valign="top">Posthumous Blue Christmas for you! <img alt="'' . substr(''//blackyak.com/dpc/bluepost.jpg'', strrpos(''//blackyak.com/dpc/bluepost.jpg'', ''/'') + 1) . ''" border="0" src="//blackyak.com/dpc/bluepost.jpg"/></td>', 'Posthumous Blue Christmas for you! ', '2009-12-19 13:46:27.000000', NULL, 1),
(5772373, 840378, 65234, '<td valign="top">Rather elaborate design there.</td>', 'Rather elaborate design there.', '2009-12-19 14:57:27.000000', NULL, 1),
(5772375, 840003, 65234, '<td valign="top">Next to a vineyard, maybe?  Wonder if there''s anything good in that junk pile.</td>', 'Next to a vineyard, maybe?  Wonder if there''s anything good in that junk pile.', '2009-12-19 14:58:40.000000', NULL, 1),
(5772377, 839716, 65234, '<td valign="top">Tonemapping works pretty well to bring out the detail here.</td>', 'Tonemapping works pretty well to bring out the detail here.', '2009-12-19 14:59:16.000000', NULL, 1),
(5772380, 839482, 65234, '<td valign="top">Someone''s trying to keep it from falling down.  Interesting that the facade sticks up above the roof.  Cool place.</td>', 'Someone''s trying to keep it from falling down.  Interesting that the facade sticks up above the roof.  Cool place.', '2009-12-19 15:00:08.000000', NULL, 1),
(5772382, 840364, 554, '<td valign="top">I''m not reminded of rural decay but it is a pretty picture...8</td>', 'I''m not reminded of rural decay but it is a pretty picture...8', '2009-12-19 15:01:29.000000', NULL, 1),
(5772383, 840429, 65234, '<td valign="top">Not much left to steal!  Nicely decrepit and the trees outside give it a more rural feel.</td>', 'Not much left to steal!  Nicely decrepit and the trees outside give it a more rural feel.', '2009-12-19 15:01:29.000000', NULL, 1),
(5772387, 840400, 65234, '<td valign="top">Interesting subject.</td>', 'Interesting subject.', '2009-12-19 15:03:09.000000', NULL, 1),
(5772388, 839397, 65234, '<td valign="top">Very scenic location.</td>', 'Very scenic location.', '2009-12-19 15:03:36.000000', NULL, 1),
(5772389, 840367, 65234, '<td valign="top">Like the old locks better than the new one; they look like they take great big skeleton keys.</td>', 'Like the old locks better than the new one; they look like they take great big skeleton keys.', '2009-12-19 15:04:12.000000', NULL, 1),
(5772390, 839534, 65234, '<td valign="top">Good subject.  The reflection adds some interest.</td>', 'Good subject.  The reflection adds some interest.', '2009-12-19 15:04:51.000000', NULL, 1),
(5772392, 840435, 65234, '<td valign="top">Almost look like a tent offering another option out back.  That house is in really bad shape!</td>', 'Almost look like a tent offering another option out back.  That house is in really bad shape!', '2009-12-19 15:05:37.000000', NULL, 1),
(5772394, 840266, 65234, '<td valign="top">Looks like it''s been dropping a few chunks of roof.  A place to stay far away from!</td>', 'Looks like it''s been dropping a few chunks of roof.  A place to stay far away from!', '2009-12-19 15:07:12.000000', NULL, 1),
(5772396, 840375, 65234, '<td valign="top">Nice, textured rust!</td>', 'Nice, textured rust!', '2009-12-19 15:07:34.000000', NULL, 1),
(5772397, 840264, 65234, '<td valign="top">Picturesque barn.</td>', 'Picturesque barn.', '2009-12-19 15:08:08.000000', NULL, 1),
(5772399, 840364, 65234, '<td valign="top">So ... the urban/suburban invasion *is* the decay?  Interesting take on the challenge.</td>', 'So ... the urban/suburban invasion *is* the decay?  Interesting take on the challenge.', '2009-12-19 15:08:58.000000', NULL, 1),
(5772401, 839458, 65234, '<td valign="top">Nice one; must have been abandoned for a long time to have such big trees so close to the buildings.</td>', 'Nice one; must have been abandoned for a long time to have such big trees so close to the buildings.', '2009-12-19 15:09:51.000000', NULL, 1),
(5772403, 840406, 65234, '<td valign="top">But still useful for storing firewood, I see.</td>', 'But still useful for storing firewood, I see.', '2009-12-19 15:10:17.000000', NULL, 1),
(5772405, 840373, 65234, '<td valign="top">I LOVE the sheep on the porch looking right at me!!!  And there is really cool detail on that porch, too.  I can''t help myself, I want a much tighter crop, like from the door to just past the sheep on the left and up just enough to get that rusty tin roof. I do love your choice of subject, I just want a closer view!</td>', 'I LOVE the sheep on the porch looking right at me!!!  And there is really cool detail on that porch, too.  I can''t help myself, I want a much tighter crop, like from the door to just past the sheep on the left and up just enough to get that rusty tin roof. I do love your choice of subject, I just want a closer view!', '2009-12-19 15:10:50.000000', NULL, 1),
(5772409, 839915, 96881, '<td valign="top">A great image.  The subtle colours through it are terrific.   Love the reflections through the pond and the use of a slow shutter speed to get the get effects through the sky.<br/>Probably marginal in really meeting the challenge, as this fence is still pretty good (at least for fences we have)......but I wont mark you down on that......others might though which would be the only thing keeping this out of the ribbons.<br/>Love the square crop as well in this.....I think it really works well here.......</td>', 'A great image.  The subtle colours through it are terrific.   Love the reflections through the pond and the use of a slow shutter speed to get the get effects through the sky.Probably marginal in really meeting the challenge, as this fence is still pretty good (at least for fences we have)......but I wont mark you down on that......others might though which would be the only thing keeping this out of the ribbons.Love the square crop as well in this.....I think it really works well here.......', '2009-12-19 15:14:31.000000', NULL, 1),
(5772412, 840289, 96881, '<td valign="top">Interesting sky in the image, but maybe slightly overprocessed for my liking.....Composition also not really appealing to me, with the house too far into the corner to really work IMHO........Don''t think all of the sky was needed as the upper part lacks real impact, so much could have been cropped out.......</td>', 'Interesting sky in the image, but maybe slightly overprocessed for my liking.....Composition also not really appealing to me, with the house too far into the corner to really work IMHO........Don''t think all of the sky was needed as the upper part lacks real impact, so much could have been cropped out.......', '2009-12-19 15:18:50.000000', NULL, 1),
(5772413, 840202, 96881, '<td valign="top">Classic composition. Great use of rule of thirds to make the watchtower the main subject, and use of the tree on the left to naturally frame the image.  LLots of small distracting elements though through the image, the stop sign, flower box in the right hand corner, cars in the background etc all dont add to the overall image........Lighting though is great and the sky is terrific.....</td>', 'Classic composition. Great use of rule of thirds to make the watchtower the main subject, and use of the tree on the left to naturally frame the image.  LLots of small distracting elements though through the image, the stop sign, flower box in the right hand corner, cars in the background etc all dont add to the overall image........Lighting though is great and the sky is terrific.....', '2009-12-19 15:22:54.000000', NULL, 1),
(5772419, 840430, 96881, '<td valign="top">Love the colours in this image.  It does have the abandoned feel.....Good composition using the rule of thirds to make the image work well........<br/>Wondering wehat the diagonal line/marks running through the image though....doesn''t make sense and does attract attention........apart from that the image is really good and one of my favourites in the challenge</td>', 'Love the colours in this image.  It does have the abandoned feel.....Good composition using the rule of thirds to make the image work well........Wondering wehat the diagonal line/marks running through the image though....doesn''t make sense and does attract attention........apart from that the image is really good and one of my favourites in the challenge', '2009-12-19 15:29:14.000000', NULL, 1),
(5772425, 840049, 96881, '<td valign="top">An image I really like, the stark tree against the fog with a scattering of snow.  Like the composition and the execution here.<br/>Not though what i had in mind for this challenge......have not marked down for this, but will be interested to see others opinions to whether this meets the challenge.........</td>', 'An image I really like, the stark tree against the fog with a scattering of snow.  Like the composition and the execution here.Not though what i had in mind for this challenge......have not marked down for this, but will be interested to see others opinions to whether this meets the challenge.........', '2009-12-19 15:46:27.000000', NULL, 1),
(5772437, 840224, 96881, '<td valign="top">Great subject......i do feel that the crop is too close.  I dont think the square crop works here.  More space on both sides would have worked better, especially if this meant that the rest of the shed was not cropped.......<br/>I like the processing you have chosen though, giving a slightly different effect to the other submissions</td>', 'Great subject......i do feel that the crop is too close.  I dont think the square crop works here.  More space on both sides would have worked better, especially if this meant that the rest of the shed was not cropped.......I like the processing you have chosen though, giving a slightly different effect to the other submissions', '2009-12-19 16:05:52.000000', NULL, 1),
(5772448, 840399, 96881, '<td valign="top">A great subject chosen.  However, I feel there is too much grass in front and not enough sky above.  A more balanced composition would have made this photo work significantly better..........</td>', 'A great subject chosen.  However, I feel there is too much grass in front and not enough sky above.  A more balanced composition would have made this photo work significantly better..........', '2009-12-19 16:20:27.000000', NULL, 1),
(5772452, 840018, 112218, '<td valign="top">Maybe too much foreground here is overwhelming the subject IMO.<br/>Sky very flat.</td>', 'Maybe too much foreground here is overwhelming the subject IMO.Sky very flat.', '2009-12-19 16:24:20.000000', NULL, 1),
(5772453, 839397, 112218, '<td valign="top">Stunning shot.<br/>Barn/building just a bit too centred.<br/>Good luck.</td>', 'Stunning shot.Barn/building just a bit too centred.Good luck.', '2009-12-19 16:25:11.000000', NULL, 1),
(5772472, 840082, 28427, '<td valign="top">What an amazing view...</td>', 'What an amazing view...', '2009-12-19 16:52:54.000000', NULL, 1),
(5772500, 840253, 56579, '<td valign="top">I don''t like the white balance</td>', 'I don''t like the white balance', '2009-12-19 17:44:59.000000', NULL, 1),
(5772532, 840082, 108982, '<td valign="top">great concept.  i think a narrower DOF would have mottled the trees in the background giving almost a studio back drop look.  Still my favorite 8.</td>', 'great concept.  i think a narrower DOF would have mottled the trees in the background giving almost a studio back drop look.  Still my favorite 8.', '2009-12-19 19:16:57.000000', NULL, 1),
(5772534, 840224, 108982, '<td valign="top">well done.  great color.  looks nearly like a painting  7</td>', 'well done.  great color.  looks nearly like a painting  7', '2009-12-19 19:19:27.000000', NULL, 1),
(5772536, 840416, 108982, '<td valign="top">nice saturation.  to help the subject project from a messy bramble.</td>', 'nice saturation.  to help the subject project from a messy bramble.', '2009-12-19 19:20:51.000000', NULL, 1),
(5772537, 840406, 108982, '<td valign="top">cool picture. timely snow.  great angle</td>', 'cool picture. timely snow.  great angle', '2009-12-19 19:21:57.000000', NULL, 1),
(5772583, 839397, 63398, '<td valign="top">There is something that just doesn''t quite work for me with this image, but I can''t put my finger on it. There''s something off......I''m actually frustrated that I can''t define it. What that leaves me with is to instead see all the things that are so right with the image, not the least of which that it is an absolutely breathtaking scene. I love the weathered, yet well-preserved old building, the detail in the mountains is fabulous, and it is a wonderful job of execution &amp; processing. 9</td>', 'There is something that just doesn''t quite work for me with this image, but I can''t put my finger on it. There''s something off......I''m actually frustrated that I can''t define it. What that leaves me with is to instead see all the things that are so right with the image, not the least of which that it is an absolutely breathtaking scene. I love the weathered, yet well-preserved old building, the detail in the mountains is fabulous, and it is a wonderful job of execution & processing. 9', '2009-12-19 20:18:37.000000', NULL, 1),
(5772585, 840054, 63398, '<td valign="top">Wonderful old piece of machinery.....I know where one of these is sitting.....must go back and shoot it! Terrific job with the moodiness......8</td>', 'Wonderful old piece of machinery.....I know where one of these is sitting.....must go back and shoot it! Terrific job with the moodiness......8', '2009-12-19 20:20:02.000000', NULL, 1),
(5772587, 839900, 63398, '<td valign="top">A classic crisp image with all the right stuff. Truly a beautiful image.....8</td>', 'A classic crisp image with all the right stuff. Truly a beautiful image.....8', '2009-12-19 20:20:49.000000', NULL, 1),
(5772591, 839868, 63398, '<td valign="top">What is "rott"? Lovely image.....I like the angle &amp; perspective.....7</td>', 'What is "rott"? Lovely image.....I like the angle & perspective.....7', '2009-12-19 20:21:59.000000', NULL, 1),
(5772592, 839439, 63398, '<td valign="top">Wonderful capture of this old place falling in on itself.....terrific find, perfect for the challenge....7</td>', 'Wonderful capture of this old place falling in on itself.....terrific find, perfect for the challenge....7', '2009-12-19 20:22:51.000000', NULL, 1),
(5772594, 840429, 61863, '<td valign="top">Productive day, getting both Urban and Country decay :) another good shot 7 from me</td>', 'Productive day, getting both Urban and Country decay :) another good shot 7 from me', '2009-12-19 20:23:32.000000', NULL, 1),
(5772595, 840269, 63398, '<td valign="top">I''m biased.....prolly shouldn''t vote this considering how much I love old decrepit faerm machinery.....7</td>', 'I''m biased.....prolly shouldn''t vote this considering how much I love old decrepit faerm machinery.....7', '2009-12-19 20:24:13.000000', NULL, 1),
(5772597, 840373, 63398, '<td valign="top">The home for wayward sheep? LOL!!! Lovely find!.....7</td>', 'The home for wayward sheep? LOL!!! Lovely find!.....7', '2009-12-19 20:24:57.000000', NULL, 1),
(5772599, 840402, 63398, '<td valign="top">Fabulous composition......7</td>', 'Fabulous composition......7', '2009-12-19 20:25:21.000000', NULL, 1),
(5772601, 840431, 63398, '<td valign="top">A wonderful discovery and truly awesome processing.....8</td>', 'A wonderful discovery and truly awesome processing.....8', '2009-12-19 20:26:50.000000', NULL, 1),
(5772606, 839716, 63398, '<td valign="top">Striking and powerful.......8</td>', 'Striking and powerful.......8', '2009-12-19 20:27:18.000000', NULL, 1),
(5772607, 839803, 63398, '<td valign="top">What a fabulous find! *SOOOOOO* jealous! I hope to see more of this! Beautifully rendered......8</td>', 'What a fabulous find! *SOOOOOO* jealous! I hope to see more of this! Beautifully rendered......8', '2009-12-19 20:28:08.000000', NULL, 1),
(5772612, 840018, 63398, '<td valign="top">Nicely done! I like the way you''ve captured the bleak feel.....7</td>', 'Nicely done! I like the way you''ve captured the bleak feel.....7', '2009-12-19 20:28:49.000000', NULL, 1),
(5772613, 839458, 63398, '<td valign="top">I''m such a freak I''d have dragged that white thing into the shed! LOL!!! Wonderful find!....7</td>', 'I''m such a freak I''d have dragged that white thing into the shed! LOL!!! Wonderful find!....7', '2009-12-19 20:29:42.000000', NULL, 1),
(5772615, 840417, 63398, '<td valign="top">Really beautiful rendition of a lovely remembrance......7</td>', 'Really beautiful rendition of a lovely remembrance......7', '2009-12-19 20:30:28.000000', NULL, 1),
(5772616, 840325, 63398, '<td valign="top">This is so outré and jarring it''s captivating......7</td>', 'This is so outré and jarring it''s captivating......7', '2009-12-19 20:31:19.000000', NULL, 1),
