(5775396, 840406, 83313, '<td valign="top">A fascinating structure. I get to wondering when looking at these, if they collapsed suddenly, or if it was a slow thing that happened over years.</td>', 'A fascinating structure. I get to wondering when looking at these, if they collapsed suddenly, or if it was a slow thing that happened over years.', '2009-12-21 13:21:27.000000', NULL, 1),
(5775397, 840390, 83313, '<td valign="top">Thanks. Now the song "Bubba shot the jukebox" is going to be stuck in my head for the next few hours. Looking forward to this challenge ending, so that I know who to blame.</td>', 'Thanks. Now the song "Bubba shot the jukebox" is going to be stuck in my head for the next few hours. Looking forward to this challenge ending, so that I know who to blame.', '2009-12-21 13:22:53.000000', NULL, 1),
(5775399, 840438, 83313, '<td valign="top">Just comes off looking a bit odd to me. Not quite sure what the issue is or is not for me.</td>', 'Just comes off looking a bit odd to me. Not quite sure what the issue is or is not for me.', '2009-12-21 13:24:55.000000', NULL, 1),
(5775981, 839916, 96881, '<td valign="top">A brilliantly composed image.  Great use of rule of thirds both in placement of the boat, and level of the water......Colours are great.  Border is subtle but very effective.  A great image</td>', 'A brilliantly composed image.  Great use of rule of thirds both in placement of the boat, and level of the water......Colours are great.  Border is subtle but very effective.  A great image', '2009-12-21 17:25:43.000000', NULL, 1),
(5775991, 840412, 96881, '<td valign="top">The subject here is very interesting, however I feel that a more interesting angle could have produced a better photo.  The image here seems a little flat, with no depth to it.  The tracks could have produced some interesting elements in this.........the crop is a little too close as well to make this work</td>', 'The subject here is very interesting, however I feel that a more interesting angle could have produced a better photo.  The image here seems a little flat, with no depth to it.  The tracks could have produced some interesting elements in this.........the crop is a little too close as well to make this work', '2009-12-21 17:28:51.000000', NULL, 1),
(5776003, 840179, 96881, '<td valign="top">Very Parched, and the image does show a different type of rural decay.......for the message you have behind this, you get a good score from me.  While most people sort out a falling down building, you (intentionally or otherwise) manage to tell a story, and make a statement.  A different placement of the elements may have added additional effect, keeping the buildings to one side more and an expanding nothingness would have sold the message further.  however, a great image that can have a story as well........</td>', 'Very Parched, and the image does show a different type of rural decay.......for the message you have behind this, you get a good score from me.  While most people sort out a falling down building, you (intentionally or otherwise) manage to tell a story, and make a statement.  A different placement of the elements may have added additional effect, keeping the buildings to one side more and an expanding nothingness would have sold the message further.  however, a great image that can have a story as well........', '2009-12-21 17:31:32.000000', NULL, 1),
(5776009, 839612, 96881, '<td valign="top">Contrast, colour, it works........The colour alone in this image makes it stand out past many others.  The snow really works here, and is perfect for the image.....great when nature works.  A different crop maybe could have improved this......it seems a little too centred in the frame for me.......</td>', 'Contrast, colour, it works........The colour alone in this image makes it stand out past many others.  The snow really works here, and is perfect for the image.....great when nature works.  A different crop maybe could have improved this......it seems a little too centred in the frame for me.......', '2009-12-21 17:33:09.000000', NULL, 1),
(5776011, 839975, 96881, '<td valign="top">Great subject, but the crop is too close for me........everything is too close to the edge, without a need to be, and without emphasizing anything for me either</td>', 'Great subject, but the crop is too close for me........everything is too close to the edge, without a need to be, and without emphasizing anything for me either', '2009-12-21 17:34:01.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5776018, 840082, 96881, '<td valign="top">Yes............Balanced, works.....not sure on the border, and some additional grass could have helped a little on balance.........</td>', 'Yes............Balanced, works.....not sure on the border, and some additional grass could have helped a little on balance.........', '2009-12-21 17:35:00.000000', NULL, 1),
(5776023, 840438, 96881, '<td valign="top">An attempt at something different, bt in my opinion, you have not managed to pull it off...........</td>', 'An attempt at something different, bt in my opinion, you have not managed to pull it off...........', '2009-12-21 17:36:01.000000', NULL, 1),
(5776027, 840390, 96881, '<td valign="top">Tight crop, multiple elements all trying to get attention....Composition really needed further work to make this image</td>', 'Tight crop, multiple elements all trying to get attention....Composition really needed further work to make this image', '2009-12-21 17:36:49.000000', NULL, 1),
(5776029, 840261, 96881, '<td valign="top">Abstract, but doesn''t really work for e........</td>', 'Abstract, but doesn''t really work for e........', '2009-12-21 17:37:15.000000', NULL, 1),
(5776034, 840246, 96881, '<td valign="top">The composition of this is a little messy, nothing really grabs the eye as the subject..........The B&amp;W does not really work for me here....and the crop is very tight</td>', 'The composition of this is a little messy, nothing really grabs the eye as the subject..........The B&W does not really work for me here....and the crop is very tight', '2009-12-21 17:39:04.000000', NULL, 1),
(5776130, 839220, 57447, '<td valign="top">Just a tad out of focus, so much for windmills as an alternative energy source.</td>', 'Just a tad out of focus, so much for windmills as an alternative energy source.', '2009-12-21 19:31:29.000000', NULL, 1),
(5776134, 840429, 57447, '<td valign="top">Great depth, processing, etc.</td>', 'Great depth, processing, etc.', '2009-12-21 19:36:07.000000', NULL, 1),
(5776719, 840179, 47470, '<td valign="top">I think this is potentially an interesting subject, but the composition doesn''t do it justice.  I would either pull back to show more of the landscape, which would make the buildings look more isolated and would put more of an emphasis on the texture created but the plows, or I would crop closer to show more detail of the buildings.  The buildings are also a little centered for my taste.  I love the uniformity of the color, but I wish there was a tiny bit more contrast to make everything pop (though the low contrast may be because I''m on a laptop).</td>', 'I think this is potentially an interesting subject, but the composition doesn''t do it justice.  I would either pull back to show more of the landscape, which would make the buildings look more isolated and would put more of an emphasis on the texture created but the plows, or I would crop closer to show more detail of the buildings.  The buildings are also a little centered for my taste.  I love the uniformity of the color, but I wish there was a tiny bit more contrast to make everything pop (though the low contrast may be because I''m on a laptop).', '2009-12-21 23:55:50.000000', NULL, 1),
(5776725, 840432, 47470, '<td valign="top">I think the wide angle distortion makes this feel bloated and unbalanced.  The gradient in the sky and contrasting highlight on the roof are gorgeous.  This was probably taken during the day, but I''d like to think it was lit by the moon--the BnW helps with the effect!</td>', 'I think the wide angle distortion makes this feel bloated and unbalanced.  The gradient in the sky and contrasting highlight on the roof are gorgeous.  This was probably taken during the day, but I''d like to think it was lit by the moon--the BnW helps with the effect!', '2009-12-21 23:58:56.000000', NULL, 1),
(5776732, 840403, 47470, '<td valign="top">Processed just enough to bring out the detail of the wood and brick, but it all still seems soft (that''s a good thing) and calm.  I half wish you had trimmed the branches, leaving only the ones that curve with the arch.  The light coming through the inner window is gorgeous.</td>', 'Processed just enough to bring out the detail of the wood and brick, but it all still seems soft (that''s a good thing) and calm.  I half wish you had trimmed the branches, leaving only the ones that curve with the arch.  The light coming through the inner window is gorgeous.', '2009-12-22 00:01:27.000000', NULL, 1),
(5776734, 840410, 47470, '<td valign="top">I wish you had taken two steps to the right.  On the branch on the bottom left, there is the start of a beautiful rim light.  Moving to the side would have put that rim light on the whole tree.  Then you could have bumped up the contrast to put the rest of the tree into true silhouette.</td>', 'I wish you had taken two steps to the right.  On the branch on the bottom left, there is the start of a beautiful rim light.  Moving to the side would have put that rim light on the whole tree.  Then you could have bumped up the contrast to put the rest of the tree into true silhouette.', '2009-12-22 00:03:42.000000', NULL, 1),
(5776741, 840246, 47470, '<td valign="top">The curtains in the window make me think someone might still live here...<br/> <br/>BnW is pretty tricky.  I''m not sure this image has enough balance between black, gray, and white to pull it off better than it would in color.  There is a lot of gray, and it is all a pretty uniform tone of gray too.<br/> <br/>A vignette/dodging and burning would have helped tell the viewer which part of the image you want us to pay attention to.  A shallower depth of field would have helped with that too.  Since your title is "Watch Your Step," it makes me think you want the view to focus on the cinder block on the ground.  Maybe get down to their level, use a shallow depth of field to focus on them, and put the out-of-focus cinder block door step and part of the door frame in the background.</td>', 'The curtains in the window make me think someone might still live here... BnW is pretty tricky.  I''m not sure this image has enough balance between black, gray, and white to pull it off better than it would in color.  There is a lot of gray, and it is all a pretty uniform tone of gray too. A vignette/dodging and burning would have helped tell the viewer which part of the image you want us to pay attention to.  A shallower depth of field would have helped with that too.  Since your title is "Watch Your Step," it makes me think you want the view to focus on the cinder block on the ground.  Maybe get down to their level, use a shallow depth of field to focus on them, and put the out-of-focus cinder block door step and part of the door frame in the background.', '2009-12-22 00:09:34.000000', NULL, 1),
(5776746, 839623, 47470, '<td valign="top">The distortion of the building makes it look important (since it gives the impression of looking up to it), but the centered composition and inclusion of so much sky at the top counter act that to make the building look small/insignificant.  Maybe move in a little, then put the building more to the right and use the fence as a leading line?</td>', 'The distortion of the building makes it look important (since it gives the impression of looking up to it), but the centered composition and inclusion of so much sky at the top counter act that to make the building look small/insignificant.  Maybe move in a little, then put the building more to the right and use the fence as a leading line?', '2009-12-22 00:13:33.000000', NULL, 1),
(5776751, 840394, 47470, '<td valign="top">This looks like a really cool barn.  I''m not really a fan of the oversaturation of the shade-blue of the roof nor of the purple border, but I like the selective focus.  It looks like it it was done in post-processing, bur it gives a nice dreamy feel.</td>', 'This looks like a really cool barn.  I''m not really a fan of the oversaturation of the shade-blue of the roof nor of the purple border, but I like the selective focus.  It looks like it it was done in post-processing, bur it gives a nice dreamy feel.', '2009-12-22 00:15:40.000000', NULL, 1),
(5776756, 839612, 47470, '<td valign="top">Nice subject (I especially love the bullet holes : ))!  I wish you had used a longer lens and a shallow depth of field to blur out the trees.  That would have left the only detail in the bullet holes to make sure that everyone sees them!</td>', 'Nice subject (I especially love the bullet holes : ))!  I wish you had used a longer lens and a shallow depth of field to blur out the trees.  That would have left the only detail in the bullet holes to make sure that everyone sees them!', '2009-12-22 00:17:52.000000', NULL, 1),
(5776760, 840082, 47470, '<td valign="top">I love the comparison between the two.  I wish you had taken a step or two to the right so that the tree wouldn''t touch the chimney.  I wonder what this would look like as a highish contrast BnW.</td>', 'I love the comparison between the two.  I wish you had taken a step or two to the right so that the tree wouldn''t touch the chimney.  I wonder what this would look like as a highish contrast BnW.', '2009-12-22 00:19:49.000000', NULL, 1),
(5776769, 839716, 47470, '<td valign="top">This might be a little overprocessed for my taste, but I must admit that it does bring out a lot of detail.  As cool as the sky looks, I''d even be conntent with a panorama crop to put the focus back on the building.</td>', 'This might be a little overprocessed for my taste, but I must admit that it does bring out a lot of detail.  As cool as the sky looks, I''d even be conntent with a panorama crop to put the focus back on the building.', '2009-12-22 00:21:38.000000', NULL, 1),
(5776783, 840433, 47470, '<td valign="top">Cool find.  You could probably crop in closer--the flowers/vines in between the doors look so interesting!  I wonder if you could use a wider aperture too to keep just the door/window in focus and blur the plants in front of them.  The color palette is very fitting for the mood of the image.  It all seems so nostalgic (in a good way).</td>', 'Cool find.  You could probably crop in closer--the flowers/vines in between the doors look so interesting!  I wonder if you could use a wider aperture too to keep just the door/window in focus and blur the plants in front of them.  The color palette is very fitting for the mood of the image.  It all seems so nostalgic (in a good way).', '2009-12-22 00:25:18.000000', NULL, 1),
(5776787, 840416, 47470, '<td valign="top">Cool find!  I love how close you cropped on this.  The colors seems a little oversaturated, but of course, it would give a totally different feel if you muted the colors.  Maybe tone down all the colors, but mute the vegetation a bit more than the tractor?</td>', 'Cool find!  I love how close you cropped on this.  The colors seems a little oversaturated, but of course, it would give a totally different feel if you muted the colors.  Maybe tone down all the colors, but mute the vegetation a bit more than the tractor?', '2009-12-22 00:27:59.000000', NULL, 1),
(5776790, 840369, 47470, '<td valign="top">I think a shallow depth of field and maybe a slightly soft focus on the whole image would make this pop.  Maybe also crop out the hot spot of the sky reflecting in the water?</td>', 'I think a shallow depth of field and maybe a slightly soft focus on the whole image would make this pop.  Maybe also crop out the hot spot of the sky reflecting in the water?', '2009-12-22 00:30:17.000000', NULL, 1),
(5776794, 840033, 47470, '<td valign="top">That looks like some strange editing.  It looks ok on the roof, but the trees (especially the one on the far left) don''t look so great, in my opinion.  I do like your title though.</td>', 'That looks like some strange editing.  It looks ok on the roof, but the trees (especially the one on the far left) don''t look so great, in my opinion.  I do like your title though.', '2009-12-22 00:31:59.000000', NULL, 1),
(5776798, 839868, 47470, '<td valign="top">The depth of field and soft colors in the clouds are perfect.</td>', 'The depth of field and soft colors in the clouds are perfect.', '2009-12-22 00:33:10.000000', NULL, 1),
(5776800, 840437, 47470, '<td valign="top">I love the play of the shadows on the wall.  I half wish you had cropped off the top and part of the right to put more emphasis on them.</td>', 'I love the play of the shadows on the wall.  I half wish you had cropped off the top and part of the right to put more emphasis on them.', '2009-12-22 00:35:13.000000', NULL, 1),
(5776801, 840367, 47470, '<td valign="top">Darn that new-looking padlock!  The original handles and locks have so much character, especially paired with that wood.</td>', 'Darn that new-looking padlock!  The original handles and locks have so much character, especially paired with that wood.', '2009-12-22 00:36:29.000000', NULL, 1),
(5776807, 840400, 47470, '<td valign="top">The buildings in the back look so interesting, but that post right in the middle is much too emphasis-heavy.  Maybe shoot through the barbed wire instead?  That way you''d still have a foreground element, but it would complement the background instead of detract from it.</td>', 'The buildings in the back look so interesting, but that post right in the middle is much too emphasis-heavy.  Maybe shoot through the barbed wire instead?  That way you''d still have a foreground element, but it would complement the background instead of detract from it.', '2009-12-22 00:42:38.000000', NULL, 1),
(5776808, 840224, 47470, '<td valign="top">I love the colors and how this feels so hazy, like an old memory.</td>', 'I love the colors and how this feels so hazy, like an old memory.', '2009-12-22 00:43:24.000000', NULL, 1),
(5776809, 840372, 47470, '<td valign="top">I''m curious as to why you selectively desaturated everything except the green.  It keeps pulling my eyes up to the tree line in the back instead of to the subject.</td>', 'I''m curious as to why you selectively desaturated everything except the green.  It keeps pulling my eyes up to the tree line in the back instead of to the subject.', '2009-12-22 00:45:01.000000', NULL, 1),
(5776812, 840323, 47470, '<td valign="top">I wish you had shot this at more of an angle.  The lines are too vertical/horizontal, which stops the image from flowing.  Everything is so compartmentalized that the eye doesn''t dance across the scene.</td>', 'I wish you had shot this at more of an angle.  The lines are too vertical/horizontal, which stops the image from flowing.  Everything is so compartmentalized that the eye doesn''t dance across the scene.', '2009-12-22 00:48:53.000000', NULL, 1),
(5776813, 840398, 47470, '<td valign="top">The absolute epitome of the country.  Perfect.</td>', 'The absolute epitome of the country.  Perfect.', '2009-12-22 00:49:24.000000', NULL, 1),
(5776814, 839220, 47470, '<td valign="top">The quality of this image makes me think it was shot on a camera phone.  I fear that will hurt you a lot in this challenge.  Your idea, however, is fabulous.</td>', 'The quality of this image makes me think it was shot on a camera phone.  I fear that will hurt you a lot in this challenge.  Your idea, however, is fabulous.', '2009-12-22 00:50:56.000000', NULL, 1),
(5776816, 839456, 47470, '<td valign="top">Great processing.  The "film" colors work very well with this.  The only thing I can say about this is that I wish you had brought out the detail in the red car, the windshield, and the grass.</td>', 'Great processing.  The "film" colors work very well with this.  The only thing I can say about this is that I wish you had brought out the detail in the red car, the windshield, and the grass.', '2009-12-22 00:53:31.000000', NULL, 1),
(5776817, 839439, 47470, '<td valign="top">I love your title, but I wish the shadows were creeping up on the building, but not yet touching it.  It takes away the emphasis of the building and takes away the tension of the story.</td>', 'I love your title, but I wish the shadows were creeping up on the building, but not yet touching it.  It takes away the emphasis of the building and takes away the tension of the story.', '2009-12-22 00:55:29.000000', NULL, 1),
(5776819, 840409, 47470, '<td valign="top">The detail of the window is incredible.  I wish you had darkened the outside just a bit to keep the emphasis on the inside.</td>', 'The detail of the window is incredible.  I wish you had darkened the outside just a bit to keep the emphasis on the inside.', '2009-12-22 00:56:31.000000', NULL, 1),
(5776821, 840404, 47470, '<td valign="top">I wish there was a little more room to the right to bring the wreath back into the frame, especially considering the title.</td>', 'I wish there was a little more room to the right to bring the wreath back into the frame, especially considering the title.', '2009-12-22 00:57:51.000000', NULL, 1),
(5776823, 840054, 47470, '<td valign="top">Lovely BnW.  I wish you pulled the exposure back up a little--the "white" snow is actually gray.</td>', 'Lovely BnW.  I wish you pulled the exposure back up a little--the "white" snow is actually gray.', '2009-12-22 01:00:15.000000', NULL, 1),
(5776824, 840261, 47470, '<td valign="top">Love the kitty paw and the Charlie Brown tree.  Nice processing too.  I''m curious as to how you did this without using an overlay.</td>', 'Love the kitty paw and the Charlie Brown tree.  Nice processing too.  I''m curious as to how you did this without using an overlay.', '2009-12-22 01:02:01.000000', NULL, 1),
(5776825, 840375, 47470, '<td valign="top">Since the rest of the scene is so tranquil, the tilt seems too rough, angry, and disorientating.</td>', 'Since the rest of the scene is so tranquil, the tilt seems too rough, angry, and disorientating.', '2009-12-22 01:03:25.000000', NULL, 1),
(5776826, 839900, 47470, '<td valign="top">Love the play of the light.</td>', 'Love the play of the light.', '2009-12-22 01:03:59.000000', NULL, 1),
(5776827, 840392, 47470, '<td valign="top">The way it''s lit up inside make me think someone''s home!  Great balance between the inside lights and the ambient light.</td>', 'The way it''s lit up inside make me think someone''s home!  Great balance between the inside lights and the ambient light.', '2009-12-22 01:05:03.000000', NULL, 1),
(5776829, 840318, 47470, '<td valign="top">Lovely processing.</td>', 'Lovely processing.', '2009-12-22 01:06:36.000000', NULL, 1),
(5776831, 839397, 47470, '<td valign="top">I feel like I''ve seen this building (with a fence in the left foreground?) in a challenge before, but I can''t find it.  Hmm.  Anyway!<br/> <br/>Great shot!  I love how the building mimics the mountains.  The shadows in the foreground add a nice touch!</td>', 'I feel like I''ve seen this building (with a fence in the left foreground?) in a challenge before, but I can''t find it.  Hmm.  Anyway! Great shot!  I love how the building mimics the mountains.  The shadows in the foreground add a nice touch!', '2009-12-22 01:09:15.000000', NULL, 1),
(5776833, 840373, 47470, '<td valign="top">I love the lamb looking at the camera!  The detail on the building is so beautifully quaint.  Awesome find.</td>', 'I love the lamb looking at the camera!  The detail on the building is so beautifully quaint.  Awesome find.', '2009-12-22 01:10:11.000000', NULL, 1),
(5776835, 839916, 47470, '<td valign="top">This seems a little dark.  The "white" clouds are definitely middle gray.  I know that darkening the sky places the emphasis on the subject, but I''d bump up that part of the image a bit too!  The play of the light is so beautiful that I''m sad to see it get lost in the darkness.</td>', 'This seems a little dark.  The "white" clouds are definitely middle gray.  I know that darkening the sky places the emphasis on the subject, but I''d bump up that part of the image a bit too!  The play of the light is so beautiful that I''m sad to see it get lost in the darkness.', '2009-12-22 01:12:58.000000', NULL, 1),
(5776838, 840429, 47470, '<td valign="top">There have been a handful of images I''ve pegged as being NikonJeb''s, but now that I''ve found a train, I''m pretty sure I''ve found him too : )  If not, good mimicry!  Great detail and leading lines.</td>', 'There have been a handful of images I''ve pegged as being NikonJeb''s, but now that I''ve found a train, I''m pretty sure I''ve found him too : )  If not, good mimicry!  Great detail and leading lines.', '2009-12-22 01:14:55.000000', NULL, 1),
(5776840, 839805, 47470, '<td valign="top">i love the layers in this: the reflection, the wall, and the window in the background.  Great processing.  It brings out the detail without being over-the-top.</td>', 'i love the layers in this: the reflection, the wall, and the window in the background.  Great processing.  It brings out the detail without being over-the-top.', '2009-12-22 01:16:13.000000', NULL, 1),
(5776841, 840430, 47470, '<td valign="top">Wow, this is great.  The colors and the mist in the background make this look so cold, which, paired with the sunset, create a nice metaphor of death.  The detail is lovely, and the triangular composition works beautifully.</td>', 'Wow, this is great.  The colors and the mist in the background make this look so cold, which, paired with the sunset, create a nice metaphor of death.  The detail is lovely, and the triangular composition works beautifully.', '2009-12-22 01:18:09.000000', NULL, 1),
(5776842, 840399, 47470, '<td valign="top">Such beautiful colors!  Great composition too.  I''m glad you didn''t HDR the heck out of it like some would--it looks beautiful as is!</td>', 'Such beautiful colors!  Great composition too.  I''m glad you didn''t HDR the heck out of it like some would--it looks beautiful as is!', '2009-12-22 01:18:33.000000', NULL, 1),
