(5780674, 840429, 67697, '<td valign="top">A <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=63398" rel="nofollow" target="_blank">NikonJeb</a> shot maybe?  The detail is awesome and the sense of depth is spectacular.  Good luck!</td>', 'A  NikonJeb shot maybe?  The detail is awesome and the sense of depth is spectacular.  Good luck!', '2009-12-24 21:15:05.000000', NULL, 1),
